/* ---- averaging ------------------------------------------------------------
 * Single-field only (like gpython_dg_mul_conf_phase): `a`/`weight`/`out` must
 * each carry exactly one basis's worth of coefficients per cell -- the
 * kernel gkyl_array_average_choose_kernel dispatches has no field-index
 * parameter at all, so a multi-field caller must loop, one field at a time,
 * in Python (dg/modal.py). */
int
gpython_array_average(
  int ndim, const double *lower, const double *upper, const int *cells, const gpython_basis *b,
  const gpython_basis *b_avg, int ndim_avg, const int *cells_avg, const int *avg_dim,
  const gpython_array *weight, const gpython_array *a, gpython_array *out
)
{
  size_t nb = (size_t)CBAS(b)->num_basis, nb_avg = (size_t)CBAS(b_avg)->num_basis;
  if (CARR(a)->ncomp != nb || CARR(out)->ncomp != nb_avg ||
      (weight && (CARR(weight)->ncomp != nb || CARR(weight)->size != CARR(a)->size))) {
    return 1;
  }

  struct gkyl_rect_grid grid;
  gkyl_rect_grid_init(&grid, ndim, lower, upper, cells);

  int ones[GKYL_MAX_DIM];
  for (int d = 0; d < ndim; ++d) {
    ones[d] = 1;
  }
  struct gkyl_range range;
  gkyl_range_init(&range, ndim, ones, cells);
  if ((size_t)range.volume != CARR(a)->size) {
    return 1;
  }

  int ones_avg[GKYL_MAX_DIM];
  for (int d = 0; d < ndim_avg; ++d) {
    ones_avg[d] = 1;
  }
  struct gkyl_range range_avg;
  gkyl_range_init(&range_avg, ndim_avg, ones_avg, cells_avg);
  if ((size_t)range_avg.volume != CARR(out)->size) {
    return 1;
  }

  /* range_avg doubles as local_avg_ext (mirrors gpython_dg_mul_conf_phase's
   * range convention: 1-indexed, lower=1, upper=cells -- there is no ghost
   * layer anywhere in the gpython boundary, so the "extended" reduced range
   * gkyl_array_average_new only reads to size the integrated weight is
   * identical to the reduced range itself). */
  struct gkyl_array_average *up = gkyl_array_average_new(
    &grid, CBAS(b), CBAS(b_avg), &range, &range_avg, &range_avg, weight ? CARR(weight) : NULL,
    avg_dim, false
  );
  gkyl_array_average_advance(up, CARR(a), ARR(out));
  gkyl_array_average_release(up);
  return 0;
}

/* ---- evaluate-and-project ------------------------------------------------- */
gpython_array *
gpython_eval_at_coord_proj(
  const gpython_basis *b, int cdim_do, int ndim, const double *lower, const double *upper,
  const int *cells, int num_eval, const int *eval_dirs, const double *eval_coords, int ndim_tar,
  const int *cells_tar, const gpython_array *in, int *out_btype, int *out_poly_order, int *out_cdim,
  int *out_vdim
)
{
  int nf = nfields_of(b, in);
  if (nf < 0 || num_eval < 1 || num_eval > ndim) {
    return NULL;
  }

  struct gkyl_rect_grid grid;
  gkyl_rect_grid_init(&grid, ndim, lower, upper, cells);

  int ones[GKYL_MAX_DIM];
  for (int d = 0; d < ndim; ++d) {
    ones[d] = 1;
  }
  struct gkyl_range rng_do;
  gkyl_range_init(&rng_do, ndim, ones, cells);
  if ((size_t)rng_do.volume != CARR(in)->size) {
    return NULL;
  }

  int ones_tar[GKYL_MAX_DIM];
  for (int d = 0; d < ndim_tar; ++d) {
    ones_tar[d] = 1;
  }
  struct gkyl_range rng_tar;
  gkyl_range_init(&rng_tar, ndim_tar, ones_tar, cells_tar);

  struct gkyl_dg_eval_at_coord_proj *up =
    gkyl_dg_eval_at_coord_proj_new(cdim_do, CBAS(b), num_eval, eval_dirs, false);

  enum gkyl_basis_type btype_tar;
  int cdim_tar, ndim_tar_full, poly_order_tar, num_basis_tar;
  gkyl_dg_eval_at_coord_proj_target_basis(
    up, &cdim_tar, &ndim_tar_full, &btype_tar, &poly_order_tar, &num_basis_tar
  );

  struct gkyl_array *out =
    gkyl_array_new(GKYL_DOUBLE, (size_t)nf * (size_t)num_basis_tar, (size_t)rng_tar.volume);

  bool pick_lower[GKYL_MAX_DIM];
  int known_index[GKYL_MAX_DIM];
  for (int d = 0; d < ndim; ++d) {
    known_index[d] = -1;
  }
  for (int i = 0; i < num_eval; ++i) {
    pick_lower[i] = false;
  }

  gkyl_dg_eval_at_coord_proj_advance(
    up, eval_coords, &grid, pick_lower, known_index, &rng_do, &rng_tar, CARR(in), out
  );
  gkyl_dg_eval_at_coord_proj_release(up);

  *out_btype = (int)btype_tar;
  *out_poly_order = poly_order_tar;
  *out_cdim = cdim_tar;
  *out_vdim = ndim_tar_full - cdim_tar;

  return (gpython_array *)out;
}

/* ---- pow(sqrt) projection -------------------------------------------------- */
int
gpython_powsqrt(
  const gpython_basis *b, int num_quad, double exponent, int ndim, const int *cells,
  gpython_array *out, const gpython_array *in
)
{
  size_t nb = (size_t)CBAS(b)->num_basis;
  if (CARR(in)->ncomp != nb || CARR(out)->ncomp != nb) {
    return 1;
  }

  int ones[GKYL_MAX_DIM];
  for (int d = 0; d < ndim; ++d) {
    ones[d] = 1;
  }
  struct gkyl_range range;
  gkyl_range_init(&range, ndim, ones, cells);
  if ((size_t)range.volume != CARR(in)->size || CARR(out)->size != CARR(in)->size) {
    return 1;
  }

  struct gkyl_proj_powsqrt_on_basis *up = gkyl_proj_powsqrt_on_basis_new(CBAS(b), num_quad, false);
  gkyl_proj_powsqrt_on_basis_advance(up, &range, exponent, CARR(in), ARR(out));
  gkyl_proj_powsqrt_on_basis_release(up);
  return 0;
}

/* ---- writing -------------------------------------------------------------- */
int
gpython_write_field(
  const char *fname, int ndim, const double *lower, const double *upper, const int *cells,
  const char *meta, size_t meta_sz, const gpython_array *a
)
{
  struct gkyl_rect_grid grid;
  gkyl_rect_grid_init(&grid, ndim, lower, upper, cells);

  int ones[GKYL_MAX_DIM];
  for (int d = 0; d < ndim; ++d) {
    ones[d] = 1;
  }
  struct gkyl_range range;
  gkyl_range_init(&range, ndim, ones, cells);
  if ((size_t)range.volume != CARR(a)->size) {
    return -1; /* sentinel: never a valid gkyl_array_rio_status value */
  }

  struct gkyl_msgpack_data md = {.meta_sz = meta_sz, .meta = (char *)meta};
  return (int)gkyl_grid_sub_array_write(&grid, &range, meta_sz ? &md : NULL, CARR(a), fname);
}

/* ---- dynvector (time-series) I/O ------------------------------------------
 * The dynvec object itself never crosses gkyl_gpython.h: it is created, filled,
 * and released entirely inside this function, and its contents move to the
 * caller only as gpython_arrays (already opaque, already RAII'd). */
int
gpython_dynvec_read(const char *fname, size_t *ncomp, gpython_array **tm, gpython_array **data)
{
  struct gkyl_dynvec_etype_ncomp info = gkyl_dynvec_read_ncomp(fname);
  if (info.ncomp == 0) {
    return 1; /* missing file or empty/unrecognized header */
  }
  if (info.type != GKYL_DOUBLE) {
    return 2; /* postgkyl only ever writes/reads double dynvectors */
  }

  gkyl_dynvec vec = gkyl_dynvec_new(GKYL_DOUBLE, info.ncomp);
  bool ok = gkyl_dynvec_read(vec, fname);
  if (!ok) {
    gkyl_dynvec_release(vec);
    return 3;
  }

  size_t n = gkyl_dynvec_size(vec);
  struct gkyl_array *tm_arr = gkyl_array_new(GKYL_DOUBLE, 1, n);
  struct gkyl_array *data_arr = gkyl_array_new(GKYL_DOUBLE, info.ncomp, n);
  gkyl_dynvec_to_array(vec, tm_arr, data_arr);
  gkyl_dynvec_release(vec);

#include <assert.h>
#include <stdbool.h>

#include <gkyl_dg_eval_at_coord_proj.h>
#include <gkyl_dg_eval_at_coord_proj_priv.h>
#include <gkyl_util.h>

struct gkyl_dg_eval_at_coord_proj *
gkyl_dg_eval_at_coord_proj_new(
  int cdim_do, const struct gkyl_basis *basis_do, int num_eval_dirs, const int *eval_dirs,
  bool use_gpu
)
{
  int ndim_do = basis_do->ndim;
  int ndim_tar = ndim_do - num_eval_dirs;

  assert(ndim_do >= 1 && ndim_do <= 6);
  assert(num_eval_dirs >= 1 && num_eval_dirs <= ndim_do);
  assert(ndim_tar == ndim_do - num_eval_dirs);
  assert(basis_do->poly_order >= 1 && basis_do->poly_order <= 3);

  struct gkyl_dg_eval_at_coord_proj *up = gkyl_calloc(1, sizeof(*up));

  up->use_gpu = use_gpu;
  up->ndim_do = ndim_do;
  up->ndim_tar = ndim_tar;
  up->num_basis_do = basis_do->num_basis;
  up->num_eval_dirs = num_eval_dirs;

  for (int i = 0; i < num_eval_dirs; i++) {
    up->eval_dirs[i] = eval_dirs[i];
  }

  for (int d = 0; d < GKYL_MAX_DIM; d++) {
    up->is_eval[d] = false;
  }

  for (int i = 0; i < num_eval_dirs; i++) {
    up->is_eval[eval_dirs[i]] = true;
  }

  up->kers =
    dg_eval_at_coord_choose_ker(use_gpu, cdim_do, ndim_do, basis_do, num_eval_dirs, eval_dirs);

  return up;
}

void
gkyl_dg_eval_at_coord_proj_advance(
  struct gkyl_dg_eval_at_coord_proj *up, const double *eval_coords,
  const struct gkyl_rect_grid *grid, const bool *pick_lower, const int *known_index,
  const struct gkyl_range *rng_do, const struct gkyl_range *rng_tar, const struct gkyl_array *fdo,
  struct gkyl_array *ftar
)
{
#ifdef GKYL_HAVE_CUDA
  if (up->use_gpu) {
    gkyl_dg_eval_at_coord_proj_advance_cu(
      up, eval_coords, grid, pick_lower, known_index, rng_do, rng_tar, fdo, ftar
    );
    return;
  }
#endif

  // We assume that if fdo has multiple DG fields (vector components), ftar has the
  // same number of vector components.
  int ncomp = fdo->ncomp / up->num_basis_do;
  int num_basis_tar = fdo->ncomp / ncomp;

  // Build full ndim_do-dimensional point for gkyl_rect_grid_find_cell.
  // Evaluated directions use eval_coords[i]; non-evaluated dirs use the
  // center of the lowest cell in rng_do for that direction.
  double point[GKYL_MAX_DIM];
  int eval_ctr = 0;
  for (int d = 0; d < up->ndim_do; d++) {
    if (up->is_eval[d]) {
      point[d] = eval_coords[eval_ctr++];
    } else {
      point[d] = grid->lower[d] + (rng_do->lower[d] - 0.5) * grid->dx[d];
    }
  }

  int cell_idx[GKYL_MAX_DIM];
  gkyl_rect_grid_find_cell(grid, point, pick_lower, known_index, cell_idx);

  // Convert comp eval_coords to logical coords.
  double eval_coords_log[GKYL_MAX_DIM];
  for (int i = 0; i < up->num_eval_dirs; i++) {
    int d = up->eval_dirs[i];
    double xc_d = grid->lower[d] + (cell_idx[d] - 0.5) * grid->dx[d];
    eval_coords_log[i] = 2.0 * (eval_coords[i] - xc_d) / grid->dx[d];
    // Force to be between -1 and 1, to account for floating point precision
    // causing results outside of [-1,1].
    eval_coords_log[i] = GKYL_MAX2(-1.0, GKYL_MIN2(eval_coords_log[i], 1.0));
  }

  int idx_do[GKYL_MAX_DIM] = {0};

  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, rng_tar);
  while (gkyl_range_iter_next(&iter)) {
    eval_at_coord_get_idx_do(up->is_eval, up->ndim_do, iter.idx, cell_idx, idx_do);

    long linidx_do = gkyl_range_idx(rng_do, idx_do);
    long linidx_tar = gkyl_range_idx(rng_tar, iter.idx);

    const double *fdo_c = gkyl_array_cfetch(fdo, linidx_do);
    double *ftar_c = gkyl_array_fetch(ftar, linidx_tar);

    for (int n = 0; n < ncomp; n++) {
      up->kers->ev_ker(eval_coords_log, fdo_c + n * up->num_basis_do, ftar_c + n * num_basis_tar);
    }
  }
}

void
gkyl_dg_eval_at_coord_proj_target_basis(
  struct gkyl_dg_eval_at_coord_proj *up, int *cdim, int *ndim, enum gkyl_basis_type *btype,
  int *poly_order, int *num_basis
)
{
  up->kers->basis_ker(cdim, ndim, btype, poly_order, num_basis);
}

void
gkyl_dg_eval_at_coord_proj_release(struct gkyl_dg_eval_at_coord_proj *up)
{
  if (!up->use_gpu) {
    gkyl_free(up->kers);
  }
#ifdef GKYL_HAVE_CUDA
  if (up->use_gpu) {
    gkyl_cu_free(up->kers);
  }
#endif
  gkyl_free(up);
}

