    }
    fprintf(fp, "}, ");

    fprintf(fp, "upper = { ");
    for (int d = 0; d < grid->ndim; ++d) {
      fprintf(fp, "%.9e%c ", grid->upper[d], d == grid->ndim - 1 ? ' ' : ',');
    }
    fprintf(fp, "}, ");

    fprintf(fp, "cells = { ");
    for (int d = 0; d < grid->ndim; ++d) {
      fprintf(fp, "%d%c ", grid->cells[d], d == grid->ndim - 1 ? ' ' : ',');
    }
    fprintf(fp, "}, ");

    fprintf(fp, "dx = { ");
    for (int d = 0; d < grid->ndim; ++d) {
      fprintf(fp, "%.9e%c ", grid->upper[d], d == grid->ndim - 1 ? ' ' : ',');
    }
    fprintf(fp, "}, ");

    fprintf(fp, " cellVolume = %.9e, ", grid->cellVolume);

    fprintf(fp, " }\n");
    fflush(fp);
)
