            np.sqrt(2 / 3) * h * (b + 2 * q * center),
            np.full_like(center,
                         np.sqrt(8 / 45) * q * h**2)
        ]
        for m, powers in enumerate(modes):
          coefficients[..., field, m] *= local[powers[d]]
